import logging
import time
from typing import Any, Callable, Dict, List, Optional, Set, Type

logger = logging.getLogger(__name__)

# Registry of named jobs
_jobs: Dict[str, Type["Job"]] = {}


class Job:
    """A scheduled job to run periodically."""

    def __init__(self, name: str, interval_seconds: int = 60, enabled: bool = True) -> None:
        self.name: str = name
        self.interval_seconds: int = interval_seconds
        self.enabled: bool = enabled
        self._last_run: float = 0.0
        self._function: Optional[Callable[..., Any]] = None

    def set_function(self, fn: Callable[..., Any]) -> None:
        self._function = fn

    def run(self) -> Any:
        """Execute the job's function."""
        if self._function is None:
            logger.warning(f"Job '{self.name}' has no function set")
            return None
        return self._function()

    def get_last_run(self) -> float:
        return self._last_run

    def set_last_run(self, timestamp: float) -> None:
        self._last_run = timestamp


def register(name: str, cls: Type[Job]) -> None:
    """Register a Job class by name."""
    _jobs[name] = cls


def get_job(name: str) -> Optional[Type[Job]]:
    """Get a Job class by name."""
    return _jobs.get(name)


def run_pending() -> None:
    """Run all pending jobs based on their intervals."""
    now = time.time()
    for job_class in _jobs.values():
        try:
            job = job_class()
            if job.enabled:
                interval = job.interval_seconds
                last_run = job.get_last_run()
                if now - last_run >= interval:
                    job.run()
                    job.set_last_run(now)
        except Exception as e:
            logger.error(f"Error running job '{job_class.__name__}': {e}")


def schedule_job(name: str, interval_seconds: int = 60, enabled: bool = True) -> Job:
